body.v20-ui .career-music-mini,
.career-music-mini{
  position:fixed!important;
  right:1.05cqw;
  bottom:1.05cqw;
  z-index:9600;
  width:10.4cqw;
  min-width:154px;
  height:2.35cqw;
  min-height:38px;
  display:grid;
  grid-template-columns:1.55cqw minmax(0,1fr) 2cqw;
