  background:rgba(249,251,254,.94);
  box-shadow:0 .35cqw 1.1cqw rgba(17,37,68,.12);
  backdrop-filter:blur(10px);
  color:#172438;
  visibility:visible;
  pointer-events:auto;
  opacity:.86;
  transition:opacity .16s ease,transform .16s ease,box-shadow .16s ease;
}
