.career-music-mini:hover{
  opacity:1;
  transform:translateY(-.05cqw);
  box-shadow:0 .45cqw 1.25cqw rgba(17,37,68,.16);
}
.career-music-icon{
  width:1.3cqw;
  height:1.25cqw;
  display:flex;
